#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    bool openParenthesis = false;
    string sb;
    int maxOutside = 0;
    int nbrInside = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == '(') {
            if (!openParenthesis) {
                vector<string> outsideWords;
                stringstream ss(sb);
                string word;
                while (getline(ss, word, '_')) {
                    outsideWords.push_back(word);
                }
                for (const auto& o : outsideWords) {
                    maxOutside = max(maxOutside, (int)o.length());
                }
            }
            openParenthesis = true;
            sb.clear();
        } else if (s[i] == ')') {
            openParenthesis = false;
            vector<string> inside;
            stringstream ss(sb);
            string word;
            while (getline(ss, word, '_')) {
                inside.push_back(word);
            }
            for (const auto& x : inside) {
                if (!x.empty()) {
                    nbrInside++;
                }
            }
            sb.clear();
        } else {
            sb += s[i];
        }
    }
    vector<string> outsideWords;
    stringstream ss(sb);
    string word;
    while (getline(ss, word, '_')) {
        outsideWords.push_back(word);
    }
    for (const auto& o : outsideWords) {
        maxOutside = max(maxOutside, (int)o.length());
    }
    cout << maxOutside << " " << nbrInside << "\n";
    return 0;
}
